// Rated fungicides for a disease profile id, best-first. Prefers the
// professional (Rutgers) source; pass source:"NC State" for home-lawn products.
export function fungicidesFor(diseaseId, source) {
  return FUNGICIDE_RATINGS
    .filter((r) => r.diseaseId === diseaseId && (!source || r.source === source))
    .sort((a, b) => b.score - a.score || a.trade.localeCompare(b.trade))
}
export function ratingsSourceFor(diseaseId) {
  const has = (s) => FUNGICIDE_RATINGS.some((r) => r.diseaseId === diseaseId && r.source === s)
  return has("Rutgers") ? "Rutgers" : has("NC State") ? "NC State" : null
}
